:root {
  color-scheme: light;
  --ink: #1b1b1f;
  --muted: #5b5b63;
  --line: #d9d9e0;
  --accent: #0f766e;
  --bg: #fafafa;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
}

#app {
  max-width: 720px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

#note-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 0.5rem;
  background: #fff;
  margin-bottom: 1.5rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.field label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--muted);
}

input,
textarea,
button {
  font: inherit;
}

input[type="text"],
input[type="search"],
textarea {
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--line);
  border-radius: 0.375rem;
  background: #fff;
  color: var(--ink);
}

textarea {
  resize: vertical;
}

input:focus-visible,
textarea:focus-visible,
button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

#note-form button[type="submit"] {
  align-self: flex-start;
  padding: 0.5rem 1.25rem;
  border: none;
  border-radius: 0.375rem;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

.search-wrap {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin-bottom: 1.5rem;
}

.search-wrap label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--muted);
}

#results-line {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
  min-height: 1.1em;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.note {
  position: relative;
  padding: 1rem 1rem 1rem 1rem;
  border: 1px solid var(--line);
  border-radius: 0.5rem;
  background: #fff;
}

.note[aria-current="true"] {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.note-avatar {
  float: right;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  margin-left: 0.75rem;
  object-fit: cover;
}

.note-title {
  display: block;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--ink);
  background: none;
  border: none;
  padding: 0;
  margin-bottom: 0.4rem;
  text-align: left;
  cursor: pointer;
}

.note-title:hover {
  color: var(--accent);
}

.note-body {
  color: var(--ink);
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--accent);
}

